import type { DatasetView } from '../../src/domain/dataset';
import { parseGeometryFile, type MapGeometry } from '../../src/geo';
import {
  createDatasetView,
  DATA_JSON_FILES,
  type DatasetFiles,
  type DatasetViewInput,
  type DataManifest,
  identityOf,
  parseManifest,
  prepareDataset,
  type PreparedDataset,
  readDataFile,
} from '../../src/infra/data';
import { datasetFilesOf, type FileContent } from '../../src/infra/data/schema';
import { type Bytes, fixtureSite, jsonOf } from './fake-fetch';

/**
 * The fixture slice (tests/fixtures/data: Durotar, generated by tools/questiedb) and the committed
 * placeholder geometry, read synchronously for tests that need a real `DatasetView` without going
 * through the loader. The loader's own tests use the same files through a fake fetch.
 */

export const SITE = fixtureSite();

export function siteManifest(site: ReadonlyMap<string, Bytes> = SITE): DataManifest {
  const parsed = parseManifest(jsonOf(site, 'data/manifest.json'));
  if (!parsed.ok) throw new Error(`fixture manifest: ${parsed.errors.join('; ')}`);
  return parsed.manifest;
}

export function siteFiles(site: ReadonlyMap<string, Bytes> = SITE): DatasetFiles {
  const contents: Partial<Record<(typeof DATA_JSON_FILES)[number], FileContent[(typeof DATA_JSON_FILES)[number]]>> = {};
  for (const file of DATA_JSON_FILES) {
    const result = readDataFile(file, jsonOf(site, `data/${file}`));
    if (!result.ok) throw new Error(`fixture ${file}: ${result.errors.join('; ')}`);
    contents[file] = result.content;
  }
  return datasetFilesOf(contents as { readonly [F in (typeof DATA_JSON_FILES)[number]]: FileContent[F] });
}

export function placeholderGeometry(site: ReadonlyMap<string, Bytes> = SITE): MapGeometry {
  const parsed = parseGeometryFile(jsonOf(site, 'maps/placeholder/geometry.placeholder.json'));
  if (!parsed.ok) throw new Error(`placeholder geometry: ${parsed.errors.join('; ')}`);
  return parsed.geometry;
}

let prepared: PreparedDataset | null = null;

/** The fixture slice prepared against the placeholder geometry (cached per test file). */
export function fixturePrepared(): PreparedDataset {
  prepared ??= prepareDataset(siteFiles(), identityOf(siteManifest()), placeholderGeometry());
  return prepared;
}

export const HORDE_WARRIOR: DatasetViewInput = { faction: 'Horde', class: 'WARRIOR', customQuests: [], questOverrides: {} };

export function fixtureView(input: DatasetViewInput = HORDE_WARRIOR): DatasetView {
  return createDatasetView(fixturePrepared(), input);
}
